/* From Uiverse.io by SelfMadeSystem  - Tags: simple, neumorphism, skeuomorphism, icon, animation, gradient, button */
.__UIV_SCOPE__ :focus {
  outline: none;
}
.__UIV_SCOPE__ ::-moz-focus-inner {
  border: 0;
}

.__UIV_SCOPE__ .border {
  position: relative;
  cursor: pointer;
  padding: 3px;
  border-radius: calc(6pt + 3px);
  appearance: none;
  font-weight: 600;
  background: linear-gradient(#dfe1e0, #7f8180);
  border: 1pt solid #e9ebea;
  border-top-width: 0;
  box-shadow: 0px 5px 15px 0px #0004;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .border::before {
  content: "";
  position: absolute;
  bottom: 0px;
  left: 0;
  right: 0;
  height: 50%;
  transition: inherit;
}

.__UIV_SCOPE__ .border:hover {
  transform: translateY(-5px);
  box-shadow: 0px 10px 15px 0px #0004;
}

.__UIV_SCOPE__ .border:hover:not(:active)::before {
  bottom: -6px;
}

.__UIV_SCOPE__ .border:active {
  transform: translateY(0px);
  box-shadow: 0px 5px 15px 0px #0000;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .outer {
  padding: 4pt;
  background: linear-gradient(#fdfffe, #eceeed, #fdfffe);
  border-radius: 6pt;
}

.__UIV_SCOPE__ .inner {
  background: linear-gradient(#eef0ef, #fafcfb, #eef0ef);
  padding: 8pt;
  border-radius: 9999px;
  display: flex;
  align-items: center;
  gap: 4pt;
  text-shadow: 0px 1px 1px #0004;
}

.__UIV_SCOPE__ .inner svg {
  filter: drop-shadow(0px 1px 0px #0007);
}

.__UIV_SCOPE__ :is(.inner, .outer) {
  background-size: 100% 200%;
  transition: background-position-y 0.5s;
}

.__UIV_SCOPE__ :active :is(.inner, .outer) {
  background-position-y: 100%;
}
